/* Reference browsing reuses curated records and explicit method–reference links. */
(()=>{
  'use strict';
  const LANGS=['zh','en','fr','es','eu'],SIZE=30;
  const COPY={
    title:['参考文献库','Reference library','Bibliothèque de références','Biblioteca de referencias','Erreferentzia-liburutegia'],
    intro:['按工具、流程与出版年份查阅文献，导出当前筛选结果。','Browse by method, workflow stage and publication year; export the filtered references.','Consultez les références par méthode, étape et année ; exportez les résultats filtrés.','Consulte por método, etapa y año; exporte las referencias filtradas.','Arakatu metodoaren, urratsaren eta argitalpen-urtearen arabera; esportatu iragazitako erreferentziak.'],
    search:['搜索题名、作者、DOI 或工具','Search title, authors, DOI or method','Rechercher titre, auteurs, DOI ou méthode','Buscar título, autores, DOI o método','Bilatu izenburua, egileak, DOI edo metodoa'],
    period:['出版时期','Publication period','Période de publication','Periodo de publicación','Argitalpen-aldia'],recent:['近十个出版年','Latest ten publication years','Dix dernières années de publication','Diez últimos años de publicación','Azken hamar argitalpen-urteak'],all:['全部','All','Tout','Todo','Guztiak'],classic:['早期文献','Earlier literature','Publications antérieures','Publicaciones anteriores','Lehenagoko argitalpenak'],unknown:['年份未载明','Year not recorded','Année non renseignée','Año no registrado','Urtea erregistratu gabe'],
    tool:['关联工具','Linked method','Méthode associée','Método vinculado','Lotutako metodoa'],stage:['流程环节','Workflow stage','Étape du protocole','Etapa del flujo','Lan-fluxuko urratsa'],type:['来源类型','Source type','Type de source','Tipo de fuente','Iturri mota'],article:['文章与章节','Articles and chapters','Articles et chapitres','Artículos y capítulos','Artikuluak eta kapituluak'],preprint:['预印本','Preprints','Prépublications','Preprints','Aurreargitalpenak'],document:['软件与文档','Software and documentation','Logiciels et documentation','Software y documentación','Softwarea eta dokumentazioa'],sort:['排序','Sort','Trier','Ordenar','Ordenatu'],newest:['年份：新到旧','Year: newest first','Année : décroissante','Año: más reciente','Urtea: berrienak lehenik'],oldest:['年份：旧到新','Year: oldest first','Année : croissante','Año: más antiguo','Urtea: zaharrenak lehenik'],plan:['仅当前方案引用','Current plan references only','Références du plan actuel','Solo referencias del plan actual','Uneko planeko erreferentziak soilik'],reset:['清除筛选','Clear filters','Effacer les filtres','Borrar filtros','Garbitu iragazkiak'],
    results:['条结果','results','résultats','resultados','emaitza'],total:['库中总计','in library','dans la bibliothèque','en la biblioteca','liburutegian'],unknownHint:['无出版年份的文档列在“年份未载明”，也可在“全部”中查看。','Undated documents appear under “Year not recorded” and “All”.','Les documents non datés figurent sous « Année non renseignée » et « Tout ».','Los documentos sin fecha aparecen en « Año no registrado » y « Todo ».','Datarik gabeko dokumentuak « Urtea erregistratu gabe » eta « Guztiak » aukeretan daude.'],
    empty:['没有匹配的参考资料','No matching references','Aucune référence correspondante','No hay referencias coincidentes','Ez dago bat datorren erreferentziarik'],emptyHint:['调整关键词或清除筛选。','Adjust the search or clear filters.','Modifiez la recherche ou effacez les filtres.','Ajuste la búsqueda o borre los filtros.','Doitu bilaketa edo garbitu iragazkiak.'],details:['阅读记录','Reading record','Fiche de lecture','Ficha de lectura','Irakurketa-fitxa'],source:['打开来源','Open source','Ouvrir la source','Abrir fuente','Ireki iturria'],authorsMissing:['作者未载明','Authors not recorded','Auteurs non renseignés','Autores no registrados','Egileak erregistratu gabe'],apa:['APA 7 引用','APA 7 citation','Référence APA 7','Cita APA 7','APA 7 aipamena'],apaExport:['导出 APA 7 与来源记录','Export APA 7 and source records','Exporter APA 7 et les sources','Exportar APA 7 y fuentes','Esportatu APA 7 eta iturriak'],bibtex:['导出 BibTeX','Export BibTeX','Exporter BibTeX','Exportar BibTeX','Esportatu BibTeX'],csl:['导出 CSL JSON','Export CSL JSON','Exporter CSL JSON','Exportar CSL JSON','Esportatu CSL JSON'],raw:['来源记录 · 引用元数据不完整','Source record · incomplete citation metadata','Source · métadonnées bibliographiques incomplètes','Fuente · metadatos bibliográficos incompletos','Iturria · aipamen-metadatu osatugabeak'],unavailable:['APA 格式化暂不可用','APA formatting unavailable','Formatage APA indisponible','Formato APA no disponible','APA formatua ez dago erabilgarri'],prev:['上一页','Previous','Précédent','Anterior','Aurrekoa'],next:['下一页','Next','Suivant','Siguiente','Hurrengoa'],page:['页','Page','Page','Página','Orria'],exported:['已导出筛选结果','Filtered references exported','Références filtrées exportées','Referencias filtradas exportadas','Iragazitako erreferentziak esportatu dira'],planUnavailable:['当前方案引用暂无法读取。','Current plan references could not be read.','Impossible de lire les références du plan actuel.','No se pudieron leer las referencias del plan actual.','Ezin izan dira uneko planeko erreferentziak irakurri.']
  };
  const A=()=>window.YV_APP,C=()=>window.YV_CITATIONS,D=()=>A()?.data()||{},list=v=>Array.isArray(v)?v:[];
  const lang=()=>LANGS.includes(A()?.prefs?.().language)?A().prefs().language:'en',T=k=>COPY[k]?.[LANGS.indexOf(lang())]||k;
  const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const norm=v=>String(v??'').normalize('NFKD').replace(/\p{M}/gu,'').toLowerCase().trim();
  const url=v=>{try{const u=new URL(v);return /^https?:$/.test(u.protocol)?u.href:'';}catch{return '';}};
  const doi=v=>C()?.normaliseDOI?.(v)||String(v||'').replace(/^https?:\/\/(?:dx\.)?doi\.org\//i,'').toLowerCase();
  const canonical=v=>C()?.canonicalURL?.(v)||url(v).replace(/\/$/,'');
  const state={query:'',period:'recent',tool:'',stage:'',type:'',sort:'newest',plan:false,page:1};
  let cache=null,hashSeen=null,planError=false;
  function year(csl,paper){const n=Number(csl?.issued?.['date-parts']?.[0]?.[0]||paper?.year);return Number.isInteger(n)&&n>0?n:null;}
  const authors=csl=>list(csl?.author).map(a=>a.literal||[a.given,a.family].filter(Boolean).join(' ')).filter(Boolean);
  const endYear=()=>Number(String(D().literature?.window?.to||'').slice(0,4))||new Date().getFullYear();
  function translated(record,key){const v=record?.[key];if(v&&typeof v==='object')return v[lang()]||v.en||'';const result=A()?.field?.(key==='title'?'steps':'tools',record,key)||A()?.tx?.(v)||v||'';return lang()!=='zh'&&/[\u3400-\u9fff]/.test(result)?record?.[key+'En']||record?.id||'':result;}
  function catalogue(){
    const papers=D().literature?.papers||[],tools=D().workflow?.tools||[],records=window.YV_CITATION_DATA?.records||[];
    if(cache?.papers===papers&&cache.tools===tools&&cache.records===records)return cache.rows;
    const groups=new Map(),recordRows=new Map();
    const key=(csl,p)=>{const d=doi(csl?.DOI||p?.doi||''),u=canonical(csl?.URL||p?.url);return d?'doi:'+d:u?'url:'+u:'id:'+(csl?.id||p?.id);};
    function obtain(k,csl){if(!groups.has(k))groups.set(k,{id:k,csl:JSON.parse(JSON.stringify(csl)),records:[],papers:[],tools:new Set(),stages:new Set()});return groups.get(k);}
    for(const record of records){const r=obtain(key(record.csl),record.csl||{id:record.id});r.records.push(record);recordRows.set(record.id,r);}
    for(const p of papers){let r=groups.get(key(null,p));if(!r){const linked=records.find(x=>x.literatureId===p.id);if(linked&&!p.doi)r=recordRows.get(linked.id);}
      if(!r){const csl={id:'library-'+p.id,type:/preprint|预印本/i.test(p.publicationType||'')?'article':p.journal?'article-journal':'article',title:p.title,URL:p.url};if(p.doi)csl.DOI=p.doi;if(p.year)csl.issued={'date-parts':[[Number(p.year)]]};if(p.journal)csl['container-title']=p.journal;if(p.authors?.length)csl.author=p.authors.map(a=>typeof a==='string'?{literal:a}:a);if(/preprint|预印本/i.test(p.publicationType||''))csl.genre='Preprint';r=obtain(key(null,p),csl);}
      r.papers.push(p);for(const id of list(p.toolIds))r.tools.add(id);
    }
    for(const tool of tools){const ids=new Set([...(C()?.toolReferenceIDs?.(tool.id)||[]),...list(tool.sourceUrls).flatMap(u=>C()?.resolve?.(u)||[])]);for(const id of ids)recordRows.get(id)?.tools.add(tool.id);
      const website=url(tool.url);if(website&&/documentation|software_repository/.test(tool.sourceKind||'')&&!/doi\.org\//i.test(website)){const k='url:'+canonical(website),r=obtain(k,{id:'documentation-'+tool.id,type:'webpage',title:tool.name,URL:website});r.tools.add(tool.id);r.document=true;}
    }
    const toolMap=new Map(tools.map(t=>[t.id,t]));
    const rows=[...groups.values()].map(r=>{r.tools=[...r.tools].filter(id=>toolMap.has(id));for(const id of r.tools)for(const step of list(toolMap.get(id).steps))r.stages.add(step);r.stages=[...r.stages];r.year=year(r.csl,r.papers[0]);r.title=String(r.csl.title||r.papers[0]?.title||r.id);r.authors=authors(r.csl);r.doi=doi(r.csl.DOI||'');r.url=url(r.csl.URL)||url(r.papers[0]?.url)||(r.doi?'https://doi.org/'+r.doi:'');r.kind=r.document||['webpage','software','dataset'].includes(r.csl.type)?'document':/preprint/i.test(r.csl.genre||'')||r.papers.some(p=>/preprint|预印本/i.test(p.publicationType||''))?'preprint':'article';r.search=norm([r.title,...r.authors,r.doi,...r.tools.map(id=>toolMap.get(id).name)].join(' '));return r;});
    cache={papers,tools,records,rows};return rows;
  }
  function planSelection(){planError=false;if(!state.plan)return null;try{const p=window.YV_BUILDER?.exported?.();if(!p)throw Error('plan');const s=p.citationSelection||{sourceUrls:p.references||[],tools:p.tools||[]};const urls=new Set(list(s.sourceUrls).map(canonical));const ids=new Set([...list(s.sourceUrls).flatMap(u=>C()?.resolve?.(u)||[]),...list(s.tools).flatMap(id=>C()?.toolReferenceIDs?.(id)||[])]);return{urls,ids};}catch{planError=true;return {urls:new Set(),ids:new Set()};}}
  function filtered(){const selected=planSelection(),tokens=norm(state.query).split(/\s+/).filter(Boolean),to=endYear(),from=to-9;return catalogue().filter(r=>(state.period==='all'||state.period==='unknown'&&!r.year||state.period==='classic'&&r.year&&r.year<from||state.period==='recent'&&r.year>=from&&r.year<=to)&&(!state.tool||r.tools.includes(state.tool))&&(!state.stage||r.stages.includes(state.stage))&&(!state.type||r.kind===state.type)&&tokens.every(t=>r.search.includes(t))&&(!selected||r.records.some(x=>selected.ids.has(x.id))||selected.urls.has(canonical(r.url)))).sort((a,b)=>a.year===null&&b.year!==null?1:b.year===null&&a.year!==null?-1:((state.sort==='oldest'?1:-1)*((a.year||0)-(b.year||0)))||a.title.localeCompare(b.title));}
  function syncHash(){const hash=globalThis.location?.hash||'';if(hash===hashSeen)return;hashSeen=hash;Object.assign(state,{query:'',period:'recent',tool:'',stage:'',type:'',sort:'newest',plan:false,page:1});const p=new URLSearchParams(hash.split('?')[1]||'');for(const k of ['tool','stage','type','period','sort'])if(p.has(k))state[k]=p.get(k);if(p.has('q'))state.query=p.get('q');if(p.has('plan'))state.plan=p.get('plan')==='1';validate();}
  function validate(){if(!['all','recent','classic','unknown'].includes(state.period))state.period='recent';if(!['','article','preprint','document'].includes(state.type))state.type='';if(!['newest','oldest'].includes(state.sort))state.sort='newest';state.page=Math.max(1,Number(state.page)||1);}
  function remember(){const p=new URLSearchParams();for(const k of ['tool','stage','type','period','sort'])if(state[k])p.set(k,state[k]);if(state.query)p.set('q',state.query);if(state.plan)p.set('plan','1');const h='#literature?'+p;hashSeen=h;if(globalThis.history?.replaceState)history.replaceState(null,'',h);}
  function setFilters(patch){Object.assign(state,patch);if(!Object.hasOwn(patch,'page'))state.page=1;validate();return filtered();}
  const select=(key,label,options)=>{if(state[key]&&!options.some(([v])=>v===state[key]))options=[...options,[state[key],state[key]]];return `<label class="ref26-filter ref26-filter-${key}" for="ref26-${key}">${E(T(label))}<select id="ref26-${key}" data-ref-filter="${key}">${options.map(([v,t])=>`<option value="${E(v)}" ${state[key]===v?'selected':''}>${E(t)}</option>`).join('')}</select></label>`;};
  function toolbar(){const tools=D().workflow?.tools||[],steps=D().workflow?.steps||[];return `<div class="ref26-filters"><label class="ref26-query" for="ref26-query">${E(T('search'))}<input id="ref26-query" type="search" data-ref-query value="${E(state.query)}" autocomplete="off"></label>${select('period','period',[['recent',`${endYear()-9}–${endYear()}`],['all',T('all')],['classic',`${T('classic')} · < ${endYear()-9}`],['unknown',T('unknown')]])}${select('sort','sort',[['newest',T('newest')],['oldest',T('oldest')]])}${select('tool','tool',[['',T('all')],...tools.map(t=>[t.id,t.name])])}${select('stage','stage',[['',T('all')],...steps.map(s=>[s.id,translated(s,'title')])])}${select('type','type',[['',T('all')],...['article','preprint','document'].map(x=>[x,T(x)])])}</div><div class="ref26-controls"><label><input type="checkbox" data-ref-plan ${state.plan?'checked':''}> ${E(T('plan'))}</label><button type="button" data-ref-reset>${E(T('reset'))}</button></div>`;}
  function card(r){return `<article class="ref26-record"><div class="ref26-meta"><span>${E(r.year||T('unknown'))}</span><span>${E(T(r.kind))}</span></div><h2>${r.papers[0]?`<button type="button" data-ref-paper="${E(r.papers[0].id)}">${E(r.title)}</button>`:r.url?`<a href="${E(r.url)}" target="_blank" rel="noopener noreferrer">${E(r.title)}</a>`:E(r.title)}</h2>${r.authors.length?`<p class="ref26-authors">${E(r.authors.slice(0,3).join('; ')+(r.authors.length>3?'; et al.':''))}</p>`:''}${r.csl['container-title']||r.csl.publisher?`<p class="ref26-journal">${E(r.csl['container-title']||r.csl.publisher)}</p>`:''}<div class="ref26-tools">${r.tools.map(id=>`<button type="button" data-ref-tool="${E(id)}">${E(D().workflow.tools.find(t=>t.id===id)?.name||id)}</button>`).join('')}</div><div class="ref26-links">${r.url?`<a href="${E(r.url)}" target="_blank" rel="noopener noreferrer">${E(r.doi?'DOI: '+r.doi:T('source'))}<span aria-hidden="true"> ↗</span></a>`:''}${r.papers[0]?`<button type="button" data-ref-paper="${E(r.papers[0].id)}">${E(T('details'))}</button>`:''}</div><details data-ref-apa="${E(r.id)}"><summary>${E(T('apa'))}</summary><div class="ref26-apa"></div></details></article>`;}
  function result(found=filtered()){const pages=Math.max(1,Math.ceil(found.length/SIZE));state.page=Math.min(state.page,pages);return `<p id="ref26-status" class="ref26-status" role="status" aria-live="polite">${found.length} ${E(T('results'))} · ${catalogue().length} ${E(T('total'))}</p>${planError?`<p role="alert">${E(T('planUnavailable'))}</p>`:''}<div class="ref26-list">${found.length?found.slice((state.page-1)*SIZE,state.page*SIZE).map(card).join(''):`<div class="ref26-empty"><h2>${E(T('empty'))}</h2><p>${E(T('emptyHint'))}</p><button type="button" data-ref-reset>${E(T('reset'))}</button></div>`}</div><nav class="ref26-pagination" aria-label="${E(T('page'))}"><button type="button" data-ref-page="${state.page-1}" ${state.page<=1?'disabled':''}>${E(T('prev'))}</button><span>${E(T('page'))} ${state.page} / ${pages}</span><button type="button" data-ref-page="${state.page+1}" ${state.page>=pages?'disabled':''}>${E(T('next'))}</button></nav>`;}
  function page(){syncHash();const found=filtered();return `<section id="reference-library-v26" class="ref26" aria-labelledby="ref26-title"><header class="ref26-header"><p class="ref26-eyebrow">YEASTVAR1011 · REFERENCES</p><h1 id="ref26-title">${E(T('title'))}</h1><p>${E(T('intro'))}</p></header>${toolbar()}<div class="ref26-export"><button type="button" data-ref-export="apa" ${found.length?'':'disabled'}>${E(T('apaExport'))}</button><button type="button" data-ref-export="bibtex" ${found.length?'':'disabled'}>${E(T('bibtex'))}</button><button type="button" data-ref-export="csl" ${found.length?'':'disabled'}>${E(T('csl'))}</button></div>${state.period==='unknown'||state.type==='document'?`<p class="ref26-hint" id="ref26-unknown-hint">${E(T('unknownHint'))}</p>`:''}<div id="ref26-results">${result(found)}</div><p id="ref26-message" role="status" aria-live="polite"></p></section>`;}
  function refresh(){const mount=document.getElementById('reference-library-v26');if(!mount)return;const box=mount.querySelector('#ref26-results');const found=filtered();if(box)box.innerHTML=result(found);const hint=mount.querySelector('#ref26-unknown-hint'),showHint=state.period==='unknown'||state.type==='document';if(hint&&!showHint)hint.remove();else if(!hint&&showHint){const node=document.createElement('p');node.id='ref26-unknown-hint';node.className='ref26-hint';node.textContent=T('unknownHint');box?.before(node);}mount.querySelectorAll('[data-ref-export]').forEach(b=>b.disabled=!found.length);remember();}
  const citeRecord=r=>r.records[0]||{id:r.csl.id,csl:r.csl,urls:[r.url].filter(Boolean)};
  const rawText=r=>[r.title,r.year,...r.authors,r.url].filter(Boolean).join('. ');
  function apa(rows){const formatted=C()?.format?.(rows.map(citeRecord));const entries=formatted?.entries||[],used=new Set(entries.map(e=>e.id));const missing=rows.filter(r=>!used.has(citeRecord(r).id));return {text:[formatted?.bibliographyText,...(missing.length?[T('raw'),...missing.map(rawText)]:[])].filter(Boolean).join('\n\n'),error:formatted?.error||null};}
  function bibtex(rows){const clean=v=>String(v??'').replace(/\\/g,'\\textbackslash{}').replace(/[{}]/g,'').replace(/[%&#_$]/g,c=>'\\'+c);return rows.map(r=>{const c=r.csl,type=c.type==='article-journal'?'article':c.type==='chapter'?'incollection':c.type==='book'?'book':'misc',fields={title:c.title,author:list(c.author).map(a=>a.literal?'{'+clean(a.literal)+'}':clean(a.family)+(a.given?', '+clean(a.given):'')).join(' and '),year:r.year,[type==='incollection'?'booktitle':'journal']:c['container-title'],volume:c.volume,number:c.issue,pages:c.page,publisher:c.publisher,doi:c.DOI,url:c.URL,note:c.genre};return '@'+type+'{'+String(c.id||r.id).replace(/[^a-zA-Z0-9_-]/g,'_')+',\n'+Object.entries(fields).filter(([,v])=>v!==null&&v!==undefined&&v!=='').map(([k,v])=>'  '+k+' = {'+(k==='author'?v:clean(v))+'}').join(',\n')+'\n}';}).join('\n\n');}
  function exportData(kind){const rows=filtered();if(kind==='csl')return {name:'yeastvar-references.csl.json',type:'application/json;charset=utf-8',text:JSON.stringify(rows.map(r=>r.csl),null,2)};if(kind==='bibtex')return {name:'yeastvar-references.bib',type:'application/x-bibtex;charset=utf-8',text:bibtex(rows)};return {name:'yeastvar-references-apa7.txt',type:'text/plain;charset=utf-8',text:apa(rows).text};}
  function download(kind){const x=exportData(kind),blob=new Blob([x.text],{type:x.type}),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=x.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),1000);const message=document.getElementById('ref26-message');if(message)message.textContent=T('exported');}
  document.addEventListener('input',event=>{if(event.target?.hasAttribute?.('data-ref-query')){setFilters({query:event.target.value});refresh();}});
  document.addEventListener('change',event=>{const t=event.target;if(t?.dataset?.refFilter){setFilters({[t.dataset.refFilter]:t.value});refresh();}else if(t?.hasAttribute?.('data-ref-plan')){setFilters({plan:t.checked});refresh();}});
  document.addEventListener('click',event=>{const t=event.target?.closest?.('[data-ref-reset],[data-ref-page],[data-ref-export],[data-ref-paper],[data-ref-tool]');if(!t)return;if(t.hasAttribute('data-ref-reset')){setFilters({query:'',tool:'',stage:'',type:'',period:'all',sort:'newest',plan:false});const mount=document.getElementById('reference-library-v26');if(mount){const wrapper=document.createElement('div');wrapper.innerHTML=page();mount.replaceWith(wrapper.firstElementChild);document.getElementById('ref26-query')?.focus();}remember();return;}if(t.dataset.refPage){setFilters({page:Number(t.dataset.refPage)});refresh();document.querySelector('#ref26-results h2 button, #ref26-results h2 a')?.focus();return;}if(t.dataset.refExport){download(t.dataset.refExport);return;}if(t.dataset.refPaper&&D().literature?.papers?.some(p=>p.id===t.dataset.refPaper))A().openRecord('paper',t.dataset.refPaper);if(t.dataset.refTool&&D().workflow?.tools?.some(x=>x.id===t.dataset.refTool))A().openRecord('tool',t.dataset.refTool);});
  document.addEventListener('toggle',event=>{const t=event.target,id=t?.dataset?.refApa;if(!id||!t.open)return;const row=catalogue().find(r=>r.id===id),target=t.querySelector('.ref26-apa');if(!row||!target||target.dataset.loaded===lang())return;const formatted=apa([row]);target.textContent=formatted.text||T('unavailable');target.dataset.loaded=lang();},true);
  window.YV_REFERENCE_LIBRARY={page,results:()=>filtered(),catalogue,exportData,setFilters,getState:()=>({...state})};
})();
